class Solution {
    public int climbStairs(int n) {
        return f(n);
    }

    private int f(int k) {
        if (k <= 2) return k;
        return f(k - 1) + f(k - 2);
    }
}

class Solution {
    public int climbStairs(int n) {
        int[] memo = new int[n + 1];
        return f(n, memo);
    }

    private int f(int k, int[] memo) {
        if (k <= 2) return k;
        if (memo[k] != 0) return memo[k];
        memo[k] = f(k - 1, memo) + f(k - 2, memo);
        return memo[k];
    }
}

class Solution {
    public int climbStairs(int n) {
        if (n <= 2) return n;
        int a = 1;
        int b = 2;
        for (int i = 3; i <= n; i++) {
            int c = a + b;
            a = b;
            b = c;
        }
        return b;
    }
}
